<?php
declare(strict_types=1);
require_once dirname(__DIR__,2).'/app/helpers/pkl.php';
$user=require_role('admin','staf_bkk');pkl_require_ready();
$id=positive_id($_GET['id']??'');if(!$id){panel_not_found();}
try{$placement=pkl_find($id);}catch(InvalidArgumentException){panel_not_found();}
$journalId=positive_id($_GET['jurnal']??'');if(isset($_GET['jurnal'])&&!$journalId){panel_not_found();}
$editing=$journalId?panel_query('SELECT * FROM pkl_journals WHERE id=:id AND placement_id=:placement',['id'=>$journalId,'placement'=>$id])->fetch():null;
if($journalId&&!$editing){panel_not_found();}
$today=date('Y-m-d');$data=$editing?:['tanggal'=>($today>=$placement['tanggal_mulai']&&$today<=$placement['tanggal_selesai']?$today:''),'kegiatan'=>'','catatan'=>''];$version=(int)($editing['version']??0);$errors=[];
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
    require_post_csrf();$action=input_text($_POST,'aksi');
    try{
        if(isset($_POST['jurnal_id'])&&!is_string($_POST['jurnal_id'])){throw new InvalidArgumentException('Jurnal tidak valid.');}
        $raw=input_text($_POST,'jurnal_id');$targetId=$raw===''?null:positive_id($raw);
        $targetVersion=(int)(filter_var($_POST['version']??null,FILTER_VALIDATE_INT)?:0);
        if(!in_array($action,['simpan','hapus'],true)||($raw!==''&&!$targetId)||($action==='hapus'&&!$targetId)){throw new InvalidArgumentException('Tindakan atau jurnal tidak valid.');}
        if($action==='simpan'){
            $journalId=$targetId;$version=$targetVersion;
            foreach(['tanggal','kegiatan','catatan'] as $key){$data[$key]=input_text($_POST,$key);}
        }
        pkl_journal_change($id,$targetId,$targetVersion,$action==='simpan'?array_intersect_key($data,array_flip(['tanggal','kegiatan','catatan'])):[],(int)$user['id'],$action==='hapus');
        panel_message($action==='hapus'?'Jurnal berhasil dihapus. Rekap mingguan ikut diperbarui.':'Jurnal harian berhasil disimpan. Rekap mingguan diperbarui otomatis.','panel/pkl/detail.php?id='.$id.'#pkl-journals');
    }catch(Throwable $exception){
        $errors[]=$exception instanceof PDOException&&($exception->errorInfo[1]??0)===1062?'Jurnal pada tanggal tersebut sudah ada. Gunakan Edit pada jurnal tanggal itu untuk menambahkan kegiatan.':pkl_error($exception);
    }
}
$journals=panel_query('SELECT * FROM pkl_journals WHERE placement_id=:id ORDER BY tanggal,id',['id'=>$id])->fetchAll();$weeks=pkl_weekly($journals);
$pages=max(1,(int)ceil(count($journals)/5));$page=min($pages,positive_id($_GET['page']??'1')??1);$visible=array_slice(array_reverse($journals),($page-1)*5,5);
$weekPages=max(1,(int)ceil(count($weeks)/5));$weekPage=min($weekPages,positive_id($_GET['week_page']??'1')??1);$visibleWeeks=array_slice(array_reverse($weeks),($weekPage-1)*5,5);
$report=panel_query('SELECT updated_at FROM pkl_final_reports WHERE placement_id=:id',['id'=>$id])->fetch();
$point=pkl_points_ready()?panel_query('SELECT latitude,longitude FROM pkl_location_points WHERE placement_id=:id',['id'=>$id])->fetch():false;
$mapsQuery=$point?$point['latitude'].','.$point['longitude']:$placement['alamat_lengkap'];
panel_start($user,'Detail PKL — '.$placement['nama'],'pkl');
?>
<div class="pkl-detail-workspace">
<header class="page-actions"><div><h1><?= panel_icon('program') ?> <?= e($placement['nama']) ?></h1><p>Jurnal kegiatan, rekap mingguan, dan laporan PKL.</p></div><nav class="pkl-detail-nav" aria-label="Pengelolaan PKL siswa"><a href="<?= e(base_url('panel/pkl/')) ?>"><?= panel_icon('back') ?> Daftar PKL</a><a href="<?= e(base_url('panel/pkl/status-siswa.php?siswa_id='.$placement['siswa_id'])) ?>"><?= panel_icon('peserta') ?> Status &amp; riwayat</a><a href="<?= e(base_url('panel/pkl/jadwal.php?placement_id='.$id)) ?>"><?= panel_icon('calendar') ?> Jadwal</a><a href="<?= e(base_url('panel/pkl/form.php?id='.$id)) ?>"><?= panel_icon('edit') ?> Penempatan</a><a href="<?= e(base_url('panel/pkl/laporan.php?id='.$id)) ?>"><?= panel_icon('lamaran') ?> Laporan akhir</a><a class="pkl-detail-export" href="<?= e(base_url('panel/pkl/unduh.php?id='.$id.'&jenis=rekap')) ?>"><?= panel_icon('download') ?> Rekap Excel</a></nav></header>
<section class="pkl-overview" aria-label="Ringkasan penempatan"><div><h2><?= panel_icon('location') ?> Tempat &amp; periode</h2><dl><div><dt>Tempat PKL</dt><dd><strong><?= e($placement['tempat_pkl']) ?></strong></dd></div><div><dt>Alamat</dt><dd><?= e($placement['alamat_lengkap']) ?> <a class="pkl-map-link" href="<?= e('https://www.google.com/maps/search/?api=1&query='.rawurlencode($mapsQuery)) ?>" target="_blank" rel="noopener noreferrer">Buka Maps</a></dd></div><div><dt>Periode</dt><dd><?= e($placement['tanggal_mulai'].' - '.$placement['tanggal_selesai']) ?></dd></div><div><dt>Kelas / jurusan</dt><dd><?= e($placement['kelas'].' / '.$placement['jurusan']) ?></dd></div></dl></div><div><h2><?= panel_icon('pengguna') ?> Pembimbing &amp; status</h2><dl><div><dt>Guru pembimbing</dt><dd><?= e($placement['guru_pembimbing']) ?></dd></div><div><dt>Pembimbing industri</dt><dd><?= e($placement['pembimbing_industri']) ?></dd></div><div><dt>Status penempatan</dt><dd><span class="badge"><?= e(pkl_status_label($placement['status'])) ?></span></dd></div><div><dt>Laporan akhir</dt><dd><?= $report?'Tersimpan':'Belum disimpan' ?><?php if($report): ?><small>Diperbarui <?= e($report['updated_at']) ?></small><?php endif; ?></dd></div></dl></div>
<p class="pkl-overview-note"><?= count($journals) ?> hari memiliki jurnal &middot; <?= count($weeks) ?> minggu tercatat. Jumlah jurnal bukan rekap kehadiran. Menyimpan laporan tidak otomatis mengubah status penempatan.</p></section>
<?php if($errors): ?><div class="notice" role="alert"><?php foreach($errors as $error): ?><p><?= e($error) ?></p><?php endforeach; ?></div><?php endif; ?>
<details id="pkl-journal-editor" class="pkl-journal-disclosure" <?= $journalId||($errors&&($action??'')==='simpan')?'open':'' ?>><summary><?= panel_icon($journalId?'edit':'add') ?> <?= $journalId?'Edit jurnal harian':'Tambah jurnal harian' ?></summary>
<form class="editor-form pkl-journal-form" method="post" action="<?= e(base_url('panel/pkl/detail.php?id='.$id)) ?>"><?= csrf_field() ?><input type="hidden" name="aksi" value="simpan"><input type="hidden" name="jurnal_id" value="<?= $journalId??'' ?>"><input type="hidden" name="version" value="<?= $version ?>">
<label class="pkl-journal-date" for="tanggal"><span><?= panel_icon('calendar') ?> Tanggal kegiatan *</span><input id="tanggal" name="tanggal" type="date" min="<?= e($placement['tanggal_mulai']) ?>" max="<?= e($placement['tanggal_selesai']) ?>" value="<?= e($data['tanggal']) ?>" required></label>
<label for="kegiatan"><span><?= panel_icon('lamaran') ?> Kegiatan *</span><textarea id="kegiatan" name="kegiatan" maxlength="10000" rows="3" required><?= e($data['kegiatan']) ?></textarea></label>
<label for="catatan"><span><?= panel_icon('message') ?> Catatan (opsional)</span><textarea id="catatan" name="catatan" maxlength="5000" rows="3"><?= e($data['catatan']) ?></textarea></label>
<div class="pkl-journal-form-footer"><small>Satu jurnal per tanggal dalam periode PKL. Tambahkan kegiatan berikutnya melalui Edit pada tanggal yang sama.</small><button type="submit"><?= panel_icon('save') ?> Simpan jurnal</button><?php if($journalId): ?><a href="<?= e(base_url('panel/pkl/detail.php?id='.$id)) ?>">Batal edit</a><?php endif; ?></div></form></details>
<section id="pkl-journals"><div class="pkl-detail-section-heading"><h2><?= panel_icon('lamaran') ?> Jurnal harian</h2><span><?= count($journals) ?> jurnal &middot; Halaman <?= $page ?> dari <?= $pages ?> &middot; Terbaru dahulu</span></div>
<div class="table-scroll pkl-detail-sheet" data-vertical-list tabindex="0" role="region" aria-label="Daftar jurnal harian"><table><thead><tr><th>Tanggal</th><th>Kegiatan</th><th>Catatan</th><th>Tindakan</th></tr></thead><tbody>
<?php foreach($visible as $row): ?><tr><td><?= e($row['tanggal']) ?></td><td><?= nl2br(e($row['kegiatan'])) ?></td><td><?= $row['catatan']!==''?nl2br(e($row['catatan'])):'&mdash;' ?></td><td><div class="pkl-journal-actions"><a href="<?= e(base_url('panel/pkl/detail.php?id='.$id.'&jurnal='.$row['id'].'#pkl-journal-editor')) ?>" title="Edit jurnal" aria-label="<?= e('Edit jurnal '.$row['tanggal']) ?>"><?= panel_icon('edit') ?></a><form method="post" action="<?= e(base_url('panel/pkl/detail.php?id='.$id)) ?>" data-confirm="Hapus jurnal tanggal ini? Rekap mingguan ikut diperbarui."><?= csrf_field() ?><input type="hidden" name="aksi" value="hapus"><input type="hidden" name="jurnal_id" value="<?= $row['id'] ?>"><input type="hidden" name="version" value="<?= $row['version'] ?>"><button class="danger" type="submit" title="Hapus jurnal" aria-label="<?= e('Hapus jurnal '.$row['tanggal']) ?>"><?= panel_icon('trash') ?></button></form></div></td></tr><?php endforeach; ?>
<?php if(!$visible): ?><tr><td colspan="4" class="empty-panel">Belum ada jurnal. Buka Tambah jurnal harian untuk mencatat kegiatan siswa pada tanggal yang sesuai.</td></tr><?php endif; ?></tbody></table></div>
<?php if($pages>1):$start=max(1,min($page-2,$pages-4));$end=min($pages,$start+4); ?><nav class="pagination pkl-journal-pagination" aria-label="Halaman jurnal"><?php if($page>1): ?><a href="<?= e(base_url('panel/pkl/detail.php?'.http_build_query(['id'=>$id,'page'=>$page-1,'week_page'=>$weekPage]).'#pkl-journals')) ?>" rel="prev"><?= panel_icon('back') ?> Sebelumnya</a><?php endif; ?><?php for($number=$start;$number<=$end;$number++): ?><a href="<?= e(base_url('panel/pkl/detail.php?'.http_build_query(['id'=>$id,'page'=>$number,'week_page'=>$weekPage]).'#pkl-journals')) ?>" aria-label="Halaman <?= $number ?>" <?= $number===$page?'aria-current="page"':'' ?>><?= $number ?></a><?php endfor; ?><?php if($page<$pages): ?><a href="<?= e(base_url('panel/pkl/detail.php?'.http_build_query(['id'=>$id,'page'=>$page+1,'week_page'=>$weekPage]).'#pkl-journals')) ?>" rel="next">Berikutnya <?= panel_icon('next') ?></a><?php endif; ?></nav><?php endif; ?></section>
<section id="pkl-weeks"><div class="pkl-detail-section-heading"><h2><?= panel_icon('tracer') ?> Rekap mingguan</h2><span><?= count($weeks) ?> minggu &middot; Halaman <?= $weekPage ?> dari <?= $weekPages ?></span></div>
<p class="pkl-week-help">Dihitung dari seluruh jurnal, Senin-Minggu. Terbaru dahulu; jumlah hari menunjukkan tanggal yang memiliki jurnal, bukan kehadiran.</p>
<div class="table-scroll pkl-detail-sheet pkl-week-sheet" data-vertical-list tabindex="0" role="region" aria-label="Rekap kegiatan mingguan"><table><thead><tr><th>Minggu / tanggal</th><th>Hari dengan jurnal</th><th>Rincian kegiatan</th><th>Catatan jurnal</th></tr></thead><tbody>
<?php foreach($visibleWeeks as $week): ?><tr><td><strong>Minggu <?= (int)substr($week['minggu'],-2) ?> &middot; <?= e(substr($week['minggu'],0,4)) ?></strong><small><?= e((new DateTimeImmutable($week['mulai']))->format('d-m-Y').' s.d. '.(new DateTimeImmutable($week['selesai']))->format('d-m-Y')) ?></small></td><td><span class="pkl-week-count"><?= (int)$week['hari'] ?> hari</span></td><td><details class="pkl-week-disclosure"><summary><?= panel_icon('calendar') ?> Lihat <?= count($week['kegiatan']) ?> kegiatan</summary><ul><?php foreach($week['kegiatan'] as $activity): ?><li><?= nl2br(e($activity)) ?></li><?php endforeach; ?></ul></details></td><td><?php if($week['catatan']): ?><details class="pkl-week-disclosure"><summary><?= panel_icon('message') ?> Lihat <?= count($week['catatan']) ?> catatan</summary><ul><?php foreach($week['catatan'] as $note): ?><li><?= nl2br(e($note)) ?></li><?php endforeach; ?></ul></details><?php else: ?><span class="pkl-week-empty">Belum ada catatan</span><?php endif; ?></td></tr><?php endforeach; ?>
<?php if(!$weeks): ?><tr><td colspan="4" class="empty-panel">Rekap muncul setelah jurnal disimpan. Minggu tanpa jurnal tidak ditampilkan.</td></tr><?php endif; ?></tbody></table></div>
<?php if($weekPages>1):$weekStart=max(1,min($weekPage-2,$weekPages-4));$weekEnd=min($weekPages,$weekStart+4); ?><nav class="pagination pkl-journal-pagination" aria-label="Halaman rekap mingguan">
<?php if($weekPage>1): ?><a rel="prev" href="<?= e(base_url('panel/pkl/detail.php?'.http_build_query(['id'=>$id,'page'=>$page,'week_page'=>$weekPage-1]).'#pkl-weeks')) ?>"><?= panel_icon('back') ?> Sebelumnya</a><?php endif; ?>
<?php for($n=$weekStart;$n<=$weekEnd;$n++): ?><a href="<?= e(base_url('panel/pkl/detail.php?'.http_build_query(['id'=>$id,'page'=>$page,'week_page'=>$n]).'#pkl-weeks')) ?>" aria-label="Rekap halaman <?= $n ?>" <?= $n===$weekPage?'aria-current="page"':'' ?>><?= $n ?></a><?php endfor; ?>
<?php if($weekPage<$weekPages): ?><a rel="next" href="<?= e(base_url('panel/pkl/detail.php?'.http_build_query(['id'=>$id,'page'=>$page,'week_page'=>$weekPage+1]).'#pkl-weeks')) ?>">Berikutnya <?= panel_icon('next') ?></a><?php endif; ?></nav><?php endif; ?></section>
</div>
<?php panel_end($user); ?>
